package com.tnr.cityguide.admin;
import com.tnr.cityguide.common.NotFoundException;import com.tnr.cityguide.place.*;import com.tnr.cityguide.city.CityRepository;import com.tnr.cityguide.storage.StorageService;import io.swagger.v3.oas.annotations.tags.Tag;import java.time.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import java.util.*;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/admin/places") @Tag(name="Admin places") public class AdminPlaceController {
 private static final Logger log=LoggerFactory.getLogger(AdminPlaceController.class);
 private final PlaceRepository places;private final CityRepository cities;private final PlaceImageRepository images;private final StorageService storage;private final PlaceService placeService;
 public AdminPlaceController(PlaceRepository p,CityRepository c,PlaceImageRepository i,StorageService s,PlaceService ps){places=p;cities=c;images=i;storage=s;placeService=ps;}
 public record PlaceRequest(String id,String cityId,String category,String name,String description,String address,String phone,String website,double lat,double lng,String opensAt,String closesAt,boolean open24h,List<Short> closedDays,String hoursText,String extra,double baseRating,Instant eventStartsAt,Instant eventEndsAt){}
 @PostMapping @Transactional public ResponseEntity<PlaceService.PlaceDetailDto> create(@RequestBody PlaceRequest r){log.info("[ADMIN_PLACE] Create requested: placeId={}, cityId={}, category={}",r.id(),r.cityId(),r.category());if(r.id()==null||places.existsById(r.id()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Place already exists.");Place p=map(r,new Place());p.setRatingAvg(p.getBaseRating());p.setReviewCount(0);places.save(p);return ResponseEntity.status(201).body(placeService.get(p.getId(),null));}
 @PutMapping("/{id}") @Transactional public PlaceService.PlaceDetailDto update(@PathVariable String id,@RequestBody PlaceRequest r){log.info("[ADMIN_PLACE] Update requested: placeId={}",id);Place p=places.findById(id).orElseThrow(()->new NotFoundException("Place not found."));if(!id.equals(r.id()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Place id cannot be changed.");map(r,p);if(p.getReviewCount()==0)p.setRatingAvg(p.getBaseRating());places.save(p);return placeService.get(id,null);}
 @DeleteMapping("/{id}") @Transactional public ResponseEntity<Void> delete(@PathVariable String id){log.info("[ADMIN_PLACE] Delete requested: placeId={}",id);Place p=places.findById(id).orElseThrow(()->new NotFoundException("Place not found."));images.findByPlaceIdOrderBySortOrderAsc(id).forEach(i->deleteAfterCommit(i.getPublicId()));places.delete(p);return ResponseEntity.noContent().build();}
 @PostMapping("/{id}/images") @Transactional public ResponseEntity<ImageDto> image(@PathVariable String id,@RequestPart("file")MultipartFile file,@RequestParam(required=false)Integer sortOrder){log.info("[ADMIN_PLACE] Image upload requested: placeId={}, filename={}, sizeBytes={}, sortOrder={}",id,file.getOriginalFilename(),file.getSize(),sortOrder);if(!places.existsById(id))throw new NotFoundException("Place not found.");StorageService.StoredImage stored=storage.store("places/"+id,file,5L*1024*1024);PlaceImage image=new PlaceImage();image.setPlaceId(id);image.setUrl(stored.url());image.setPublicId(stored.publicId());image.setSortOrder(sortOrder==null?images.findByPlaceIdOrderBySortOrderAsc(id).size():sortOrder);image=images.save(image);return ResponseEntity.status(201).body(new ImageDto(image.getId(),image.getUrl(),image.getSortOrder()));}
 @DeleteMapping("/{id}/images/{imageId}") @Transactional public ResponseEntity<Void> deleteImage(@PathVariable String id,@PathVariable UUID imageId){log.info("[ADMIN_PLACE] Image removal requested: placeId={}, imageId={}",id,imageId);PlaceImage image=images.findById(imageId).orElseThrow(()->new NotFoundException("Image not found."));if(!image.getPlaceId().equals(id))throw new NotFoundException("Image not found.");deleteAfterCommit(image.getPublicId());images.delete(image);return ResponseEntity.noContent().build();}
 private void deleteAfterCommit(String id){if(id==null||id.isBlank())return;if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){storage.delete(id);}});}
 private Place map(PlaceRequest r,Place p){if(r.cityId()==null||!cities.existsById(r.cityId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"City not found.");if(!Set.of("attraction","restaurant","hotel","event").contains(r.category()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown category.");if(r.id()==null||!r.id().matches("[a-z0-9-]{2,40}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid place id.");if((r.opensAt()==null)!=(r.closesAt()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Opening and closing times must both be present or absent.");if(r.baseRating()<1||r.baseRating()>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Base rating must be between 1 and 5.");if(r.closedDays()!=null&&r.closedDays().stream().anyMatch(d->d==null||d<1||d>7))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Closed days must be between 1 and 7.");if("event".equals(r.category())){if(r.eventStartsAt()==null||r.eventEndsAt()==null||!r.eventEndsAt().isAfter(r.eventStartsAt()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Events require an end time after the start time.");}else if(r.eventStartsAt()!=null||r.eventEndsAt()!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only events can have event dates.");p.setId(r.id());p.setCityId(r.cityId());p.setCategory(r.category());p.setName(r.name());p.setDescription(r.description());p.setAddress(r.address());p.setPhone(r.phone()==null?"":r.phone());p.setWebsite(r.website()==null?"":r.website());p.setLat(r.lat());p.setLng(r.lng());try{p.setOpensAt(r.opensAt()==null?null:LocalTime.parse(r.opensAt()));p.setClosesAt(r.closesAt()==null?null:LocalTime.parse(r.closesAt()));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Opening times must use HH:mm.");}p.setOpen24h(r.open24h());if(r.closedDays()==null)p.setClosedDays(null);else{short[] days=new short[r.closedDays().size()];for(int i=0;i<days.length;i++)days[i]=r.closedDays().get(i);p.setClosedDays(days);}p.setHoursText(r.hoursText());p.setExtra(r.extra()==null?"":r.extra());p.setBaseRating(r.baseRating());p.setEventStartsAt(r.eventStartsAt());p.setEventEndsAt(r.eventEndsAt());return p;}
 public record ImageDto(UUID id,String url,int sortOrder){}
}